from contextlib import contextmanager
events = []
@contextmanager
def resource():
    events.append('准备')
    try:
        yield '测试资源'
    finally:
        events.append('归还')
try:
    with resource() as value:
        events.append(value)
        raise ValueError('模拟失败')
except ValueError:
    events.append('已定位')
print(events)

